using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var relevance = new RelevanceEvaluator();
        var result = await relevance.EvaluateAsync(messages, _evaluatorClient);

        foreach (var metric in result)
        {
            Assert.IsFalse(metric.Interpretation?.Rating == EvaluationRating.Inconclusive,
                $"Metric '{metric.Name}' was inconclusive.");
            Assert.IsFalse(metric.Interpretation?.Rating == EvaluationRating.Unacceptable,
                $"Metric '{metric.Name}' rated unacceptable: {metric.Reason}");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsCoherent()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in simple terms.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var coherence = new CoherenceEvaluator();
        var result = await coherence.EvaluateAsync(messages, _evaluatorClient);

        foreach (var metric in result)
        {
            Assert.IsFalse(metric.Interpretation?.Rating == EvaluationRating.Unacceptable,
                $"Metric '{metric.Name}' rated unacceptable: {metric.Reason}");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsFluent()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Write a brief summary of the water cycle.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var fluency = new FluencyEvaluator();
        var result = await fluency.EvaluateAsync(messages, _evaluatorClient);

        foreach (var metric in result)
        {
            Assert.IsFalse(metric.Interpretation?.Rating == EvaluationRating.Unacceptable,
                $"Metric '{metric.Name}' rated unacceptable: {metric.Reason}");
        }
    }
}

